USE my_databse;
-- 1. WHAT IS THE TOTAL REVENUE GENERATED BY MALE AND FEMALE CUSTOMERS
SELECT gender, SUM(purchase_amount) AS TOTAL_REVENUE FROM customer GROUP BY gender;
-- 2. WHICH CUSTOMER USED THE DISCOUNT BUT STILL SPENT MORE THAN AVERAGE PURCHASE AMOUNT
SELECT customer_id, purchase_amount FROM customer 
WHERE discount_applied="YES" AND purchase_amount>=(SELECT AVG(purchase_amount) FROM customer);
-- 3. WHICH ARE THE TOP 5 PRODUCTS WITH THE HIGHEST AVERAGE REVIEW RATING
SELECT item_purchased, AVG(review_rating) AS AVG_RATING FROM customer 
GROUP BY item_purchased 
ORDER BY AVG(review_rating) DESC LIMIT 5;
-- 4. COMPARE THE AVERAGE PURCHASE AMOUNT BETWEEN STANDARD AND EXPRESS SHIPPING 
SELECT shipping_type, ROUND(AVG(purchase_amount)) AS AVG_AMOUNT FROM customer
WHERE shipping_type IN ('Standard', 'Express') GROUP BY shipping_type;
-- 5. DO SUBSCRIBED CUSTOMERS SPENT MORE? COMPARE AVERAGE SPEND AND TOTAL REVENUE BETWEEN SUBSCRIBER AND NON SUBSCRIBER
SELECT subscription_status, COUNT(customer_id) AS TOTAL_CUSTOMERS, ROUND(AVG(purchase_amount)) AS AVG_SPEND, 
ROUND(SUM(purchase_amount),2) AS TOTAL_REVENUE FROM customer GROUP BY subscription_status ORDER BY total_revenue, avg_spend DESC;
-- 6. WHICH 5 PRODUCT HAVE THE HIGHEST PERCENTAGE OF PURCHASES WITH DISCOUNT APPLIED
SELECT item_purchased, ROUND(100 * SUM(case when discount_applied ='yes' then 1 else 0 end ) /COUNT(*) ,2) as discount_rate FROM customer 
GROUP BY item_purchased ORDER by discount_rate DESC LIMIT 5;
-- 7. SEGMENT CUSTOMERS INTO NEW, RETURNING AND LOYAL BASED ON THEIR TOTAL NUMBER OF PREVIOUS PURCHASES AND SHOW EACH SEGMENT 
with customer_type as( 
select customer_id, previous_purchases, 
case 
    when previous_purchases=1 then "new"
    when previous_purchases between 2 and 10 then 'returning'
    else 'loyal'
    end as customer_segment 
from customer)
select customer_segment, count(*) as 'no of customer' from customer_type
group by customer_segment; 
--  8. WHAT ARE TOP 3 MOST PURCHASED PRODUCTS WITHIN EACH CATEGORY
with item_counts as (
select category, item_purchased, count(customer_id) as total_orders,
ROW_NUMBER() over(partition by category order by count(customer_id )desc) as item_rank
from customer
group by category, item_purchased 
)
select item_rank, category, item_purchased, total_orders from item_counts where item_rank<=3;
-- 9. are customers who are repeat buyers(more than 5 purchases) also likely to subscribe
select subscription_status, count(customer_id) as repeat_buyers from customer where previous_purchases>5
group by subscription_status;
-- 10. what is the revenue contribution of each age group 
select age_group, sum(purchase_amount) as total_revenue from customer group by age_group 
order by total_revenue desc;